_sum, _max, _min, _round = _bi.sum, _bi.max, _bi.min, _bi.round

DEFAULTS = {
    'units':        ['customer', 'txn'],   # count by distinct customers, by transactions, or both
    'peer_cols':    [],                    # e.g. ['seller_group', 'h3_9']; [] = no peer test
    'min_peers':    3,                     # other sellers needed in the peer group
    'peer_fallback_cols': [],              # e.g. ['seller_group']: coarser group used when the first has too few sellers
    'anchor_start': None,                  # 'YYYY-MM-DD'; None = first day with every window inside the data
    'anchor_end':   None,                  # 'YYYY-MM-DD'; None = last day in df
    'skip_last_day': False,                # True: drop the last day in df (partly loaded)
    'min_total':    10,                    # recent-window count needed (seller, and peers)
    'min_flag':     5,                     # flagged count needed in the recent window (volume: seller count)
    'q_max':        0.05,                  # Benjamini-Hochberg q-value to fire
    'or_min':       2.0,                   # odds ratio needed to fire
    'cooldown':     7,                     # days before the same rule can alert the same seller again
    'bh_scope':     'rule',                # 'rule': BH over sellers per day and rule; 'day': over every rule that day
    'max_rows':     3_000_000,             # most test rows brought into pandas
    'susp_cond':    None,                  # SQL condition marking a suspicious transaction
    'susp_date_col': None,                 # optional: date the flag was raised (else the transaction date)
    'def_col':      None,                  # 0/1 default flag per transaction
    'obs_col':      None,                  # 0/1 observed (matured) flag per transaction
    'lift_days':    30,                    # forward default lift: loans in the N days after an alert
}


def _log(msg):
    print(msg, flush=True)


# ---------------------------------------------------------------------------- Fisher
def _logfact_fn(max_n):
    """log(n!) as a vectorised lookup (table up to max_n), exact to ~1e-9."""
    max_n = int(max_n)
    if max_n <= 50_000_000:
        tab = np.zeros(max_n + 2)
        tab[2:] = np.cumsum(np.log(np.arange(2, max_n + 2, dtype=float)))
        return lambda x: tab[np.asarray(x, dtype=np.int64)]
    lg = np.frompyfunc(lambda v: math.lgamma(v + 1.0), 1, 1)
    return lambda x: np.asarray(lg(np.asarray(x, dtype=float)), dtype=float)


def fisher_greater(a, b, c, d):
    """One-sided Fisher exact test, alternative 'greater', for 2x2 tables [[a, b], [c, d]].

    p = P(X >= a), X hypergeometric with the table margins fixed. Same as
    scipy.stats.fisher_exact(table, alternative='greater'). Vectorised over arrays."""
    a, b, c, d = (np.asarray(v, dtype=np.int64) for v in (a, b, c, d))
    n_rows = a.size
    p = np.ones(n_rows)
    if n_rows == 0:
        return p
    N, K, n = a + b + c + d, a + c, a + b                  # population, successes, draws
    lo, hi = np.maximum(0, n + K - N), np.minimum(n, K)
    lf = _logfact_fn(N.max())
    lc = lambda x, y: lf(x) - lf(y) - lf(x - y)
    mode = np.floor((n + 1.0) * (K + 1.0) / (N + 2.0)).astype(np.int64)

    def logpmf(x, i):
        return lc(K[i], x) + lc(N[i] - K[i], n[i] - x) - lc(N[i], n[i])

    up = a > mode                                          # tail above the mode: sum upward from a
    idx = np.where(up)[0]
    if idx.size:
        j = a[idx].copy(); term = np.ones(idx.size); tot = np.ones(idx.size)
        Ki, ni, Ni, hii = K[idx], n[idx], N[idx], hi[idx]
        act = np.arange(idx.size)
        while act.size:
            jj = j[act]
            r = (Ki[act] - jj) * (ni[act] - jj) / ((jj + 1.0) * (Ni[act] - Ki[act] - ni[act] + jj + 1.0))
            r = np.where(jj >= hii[act], 0.0, r)
            term[act] *= r; tot[act] += term[act]; j[act] += 1
            act = act[(term[act] > 1e-17 * tot[act]) & (j[act] < hii[act])]
        p[idx] = np.exp(logpmf(a[idx], idx)) * tot
    idx = np.where(~up & (a - 1 >= lo))[0]                 # otherwise p = 1 - P(X <= a-1): sum downward
    if idx.size:
        j = a[idx] - 1; term = np.ones(idx.size); tot = np.ones(idx.size)
        Ki, ni, Ni, loi = K[idx], n[idx], N[idx], lo[idx]
        act = np.arange(idx.size)
        while act.size:
            jj = j[act]
            r = jj * (Ni[act] - Ki[act] - ni[act] + jj) / ((Ki[act] - jj + 1.0) * (ni[act] - jj + 1.0))
            r = np.where(jj <= loi[act], 0.0, r)
            term[act] *= r; tot[act] += term[act]; j[act] -= 1
            act = act[(term[act] > 1e-17 * tot[act]) & (j[act] > loi[act])]
        p[idx] = 1.0 - np.exp(logpmf(a[idx] - 1, idx)) * tot
    return np.clip(p, 0.0, 1.0)


def odds_ratio(a, b, c, d):
    """Odds ratio with 0.5 added to every cell, and its 95% (Woolf) interval."""
    a, b, c, d = (np.asarray(v, dtype=float) + 0.5 for v in (a, b, c, d))
    o = a * d / (b * c)
    se = np.sqrt(1 / a + 1 / b + 1 / c + 1 / d)
    return o, np.exp(np.log(o) - 1.96 * se), np.exp(np.log(o) + 1.96 * se)


def bh_qvalues(p, n_family):
    """Benjamini-Hochberg q-values for p (one family) when the family has n_family tests in all.
    Tests left out of p all have larger p-values, so the ranks below them are unchanged."""
    p = np.asarray(p, dtype=float)
    if p.size == 0:
        return p
    order = np.argsort(p, kind='mergesort')
    ranks = np.arange(1, p.size + 1)
    q = p[order] * float(n_family) / ranks
    q = np.minimum.accumulate(q[::-1])[::-1]
    out = np.empty_like(q); out[order] = np.minimum(q, 1.0)
    return out


# ---------------------------------------------------------------------------- Spark counts
def _windows(comparisons):
    """Distinct day windows (start, end) used by all comparisons; day 1 = the anchor day."""
    ws = []
    for cmp_ in comparisons:
        for w in (tuple(cmp_['recent']), tuple(cmp_['base'])):
            if w not in ws:
                ws.append(w)
    return ws


def _spark_counts(base, unit, metrics, wins, levels, a_start, a_end, spark):
    """Counts per seller x anchor day x window: n (total), f_<k> (flagged) for each flag metric,
    all_n (every seller), and for each peer level ('p' = peer group, 'p2' = fallback group) the
    same counts for the other sellers: <lvl>_n, <lvl>_m (other sellers), <lvl>_f_<k>.
    Counting by customers, the peer row leaves out every customer of this seller (disjoint rows)."""
    from pyspark.sql import functions as F
    flags = [m['name'] for m in metrics if m['kind'] == 'flag']
    W = spark.createDataFrame([(i, int(s), int(e)) for i, (s, e) in enumerate(wins)], 'w int, ws int, we int')
    gk = ['_g', '_g2']
    if unit == 'customer':
        r0 = base.groupBy(*gk, '_m', '_c', '_d').agg(*[F.max('_f_' + k).alias('_f_' + k) for k in flags])
    else:
        r0 = base.groupBy(*gk, '_m', '_d').agg(F.count(F.lit(1)).alias('_n'),
                                               *[F.sum('_f_' + k).alias('_f_' + k) for k in flags])
    lo = F.greatest(F.expr('date_add(_d, ws - 1)'), F.lit(a_start).cast('date'))
    hi = F.least(F.expr('date_add(_d, we - 1)'), F.lit(a_end).cast('date'))
    x = (r0.crossJoin(F.broadcast(W)).withColumn('_lo', lo).withColumn('_hi', hi)
         .where(F.col('_lo') <= F.col('_hi'))
         .withColumn('_t', F.explode(F.sequence('_lo', '_hi'))).drop('_lo', '_hi', 'ws', 'we', '_d'))
    key = gk + ['_m', '_t', 'w']
    cached = []
    if unit == 'customer':
        A = x.groupBy(*gk, '_m', '_c', '_t', 'w').agg(*[F.max('_f_' + k).alias('_f_' + k) for k in flags]).persist()
        cached.append(A)
        M = A.groupBy(*key).agg(F.count(F.lit(1)).alias('n'), *[F.sum('_f_' + k).alias('f_' + k) for k in flags])
        tot = A.select('_c', '_t', 'w').distinct().groupBy('_t', 'w').agg(F.count(F.lit(1)).alias('all_n'))
    else:
        M = x.groupBy(*key).agg(F.sum('_n').alias('n'), *[F.sum('_f_' + k).alias('f_' + k) for k in flags])
        tot = M.groupBy('_t', 'w').agg(F.sum('n').alias('all_n'))
    out = M.join(tot, ['_t', 'w'])
    for lvl, gc in levels:                                  # e.g. [('p', '_g'), ('p2', '_g2')]
        nm = M.groupBy(gc, '_t', 'w').agg(F.countDistinct('_m').alias('_gm'))
        if unit == 'customer':
            C = A.groupBy(gc, '_c', '_t', 'w').agg(*[F.max('_f_' + k).alias('_cf_' + k) for k in flags])
            G = C.groupBy(gc, '_t', 'w').agg(F.count(F.lit(1)).alias('_gn'),
                                             *[F.sum('_cf_' + k).alias('_gf_' + k) for k in flags])
            X = (A.select(gc, '_m', '_c', '_t', 'w').distinct().join(C, [gc, '_c', '_t', 'w'])
                 .groupBy(gc, '_m', '_t', 'w').agg(F.count(F.lit(1)).alias('_xn'),
                                                   *[F.sum('_cf_' + k).alias('_x_' + k) for k in flags]))
            P = (G.join(nm, [gc, '_t', 'w']).join(X, [gc, '_t', 'w'])
                 .select(gc, '_m', '_t', 'w', (F.col('_gn') - F.col('_xn')).alias(lvl + '_n'),
                         (F.col('_gm') - 1).alias(lvl + '_m'),
                         *[(F.col('_gf_' + k) - F.col('_x_' + k)).alias(lvl + '_f_' + k) for k in flags]))
        else:
            G = M.groupBy(gc, '_t', 'w').agg(F.sum('n').alias('_gn'), *[F.sum('f_' + k).alias('_gf_' + k) for k in flags])
            S = M.groupBy(gc, '_m', '_t', 'w').agg(F.sum('n').alias('_sn'), *[F.sum('f_' + k).alias('_s_' + k) for k in flags])
            P = (G.join(nm, [gc, '_t', 'w']).join(S, [gc, '_t', 'w'])
                 .select(gc, '_m', '_t', 'w', (F.col('_gn') - F.col('_sn')).alias(lvl + '_n'),
                         (F.col('_gm') - 1).alias(lvl + '_m'),
                         *[(F.col('_gf_' + k) - F.col('_s_' + k)).alias(lvl + '_f_' + k) for k in flags]))
        out = out.join(P, [gc, '_m', '_t', 'w'], 'left')
    return out, cached


def _spark_tests(counts, unit, metrics, comparisons, wins, levels, cfg, spark):
    """One row per seller x anchor x metric x comparison x test with the 2x2 table a, b, c, d.
    One join for all comparisons, then one explode over metrics x tests (no unions)."""
    from pyspark.sql import functions as F
    flags = [m['name'] for m in metrics if m['kind'] == 'flag']
    lv = [l for l, _ in levels]
    cols = ['n', 'all_n'] + ['f_' + k for k in flags] + \
        [l + c for l in lv for c in ['_n', '_m'] + ['_f_' + k for k in flags]]
    cmp_df = spark.createDataFrame([(c['name'], wins.index(tuple(c['recent'])), wins.index(tuple(c['base'])))
                                    for c in comparisons], 'comparison string, wr int, wb int')
    gk = ['_g', '_g2']
    R = counts.join(F.broadcast(cmp_df), counts['w'] == cmp_df['wr']).select(
        *gk, '_m', '_t', 'comparison', 'wb', *[F.col(c).alias('r_' + c) for c in cols])
    B = counts.select(*gk, '_m', '_t', F.col('w').alias('wb'), *[F.col(c).alias('b_' + c) for c in cols])
    Ball = counts.select('_t', F.col('w').alias('wb'), F.col('all_n').alias('ball')).distinct()
    J = R.join(B, gk + ['_m', '_t', 'wb'], 'left').join(Ball, ['_t', 'wb'], 'left')
    z = lambda c: F.coalesce(F.col(c), F.lit(0)).cast('long')
    nr, nb = z('r_n'), z('b_n')
    none = F.lit(None).cast('long')
    if lv:
        # peer group, or the fallback group when the peer group has fewer than min_peers other sellers
        fine = (z('r_p_m') >= cfg['min_peers']) if len(lv) == 2 else F.lit(True)
        pick = lambda pre, c: F.when(fine, z(pre + 'p_' + c)).otherwise(z(pre + lv[-1] + '_' + c))
        level = F.when(fine, F.lit('group')).otherwise(F.lit('fallback'))
        group = F.when(fine, F.col('_g')).otherwise(F.col('_g2'))
    else:
        level = group = F.lit(None).cast('string')
    items = []
    for m in metrics:
        k = m['name']
        if m['kind'] == 'flag':
            fr, fb = z('r_f_' + k), z('b_f_' + k)
            items.append((k, 'self', fr, nr - fr, fb, nb - fb, fr, none))
            if lv:
                pf, pn = pick('r_', 'f_' + k), pick('r_', 'n')
                items.append((k, 'peer', fr, nr - fr, pf, pn - pf, fr, pick('r_', 'm')))
        else:  # volume: seller vs everyone else (self) or vs its peers (peer), recent vs base
            items.append((k, 'self', nr, z('r_all_n') - nr, nb, z('ball') - nb, nr, none))
            if lv:
                items.append((k, 'peer', nr, pick('r_', 'n'), nb, pick('b_', 'n'), nr, pick('r_', 'm')))
    structs = []
    for k, test, a, b, c, d, flagged, pm in items:
        gate = (nr >= cfg['min_total']) & (flagged >= cfg['min_flag'])
        if test == 'peer':
            gate = gate & (pm >= cfg['min_peers']) & (pick('r_', 'n') >= cfg['min_total'])
        structs.append(F.when(gate, F.struct(F.lit(k).alias('metric'), F.lit(test).alias('test'),
                                             a.alias('a'), b.alias('b'), c.alias('c'), d.alias('d'),
                                             (pm if test == 'peer' else none).alias('peer_sellers'),
                                             (level if test == 'peer' else F.lit(None).cast('string')).alias('peer_level'),
                                             (group if test == 'peer' else F.lit(None).cast('string')).alias('peer_group'))))
    x = J.select(F.col('_t').alias('anchor'), F.col('_m').alias('merchant'),
                 'comparison', F.explode(F.array(*structs)).alias('s')).where(F.col('s').isNotNull())
    return x.select('anchor', 'merchant', 's.peer_group', 's.metric', 'comparison', F.lit(unit).alias('unit'),
                    's.test', 's.a', 's.b', 's.c', 's.d', 's.peer_sellers', 's.peer_level')


# ---------------------------------------------------------------------------- pandas steps
def _alerts(det, cooldown):
    """alert = a fired day at least `cooldown` days after this rule last alerted this seller."""
    det['alert'] = False
    f = det[det['fired']].sort_values('anchor')
    keys = ['merchant', 'metric', 'comparison', 'unit', 'test']
    keep = []
    for _, g in f.groupby(keys, sort=False):
        last = None
        for i, t in zip(g.index, g['anchor']):
            if last is None or (t - last).days >= cooldown:
                keep.append(i); last = t
    det.loc[keep, 'alert'] = True
    return det


def _expand(merch, start, offsets):
    """(seller, day) pairs: every start day shifted by every offset (days)."""
    merch, start = np.asarray(merch), pd.to_datetime(pd.Series(start)).values
    off = np.asarray(offsets, dtype='timedelta64[D]')
    out = pd.DataFrame({'merchant': np.repeat(merch, len(off)),
                        'day': np.repeat(start, len(off)) + np.tile(off, len(merch))})
    return out.drop_duplicates()


def _rate(L):
    o = L['obs_n'].sum()
    return (L['def_n'].sum() / o) if o else np.nan


def _summary(det, fam, n_days, comparisons, metrics, susp, loans, a_start, a_end, lift_days):
    keys = ['metric', 'comparison', 'unit', 'test']
    kind = {m['name']: m['kind'] for m in metrics}
    rec = {c['name']: tuple(c['recent']) for c in comparisons}
    tests = fam.groupby(keys)['n_tests'].sum()
    r4 = lambda v: _round(float(v), 4) if v == v else np.nan
    r2 = lambda v: _round(float(v), 2) if v == v else np.nan
    rows = []
    for k, g in det.groupby(keys, sort=False):
        fired, al = g[g['fired']], g[g['alert']]
        r = dict(zip(keys, k))
        r['rule_type'] = kind.get(k[0], 'flag')
        r.update(tests=int(tests.get(k, 0)), fired=len(fired), alerts=len(al),
                 alerts_per_day=_round(len(al) / _max(n_days, 1), 2), sellers_alerted=al['merchant'].nunique())
        if susp is not None:
            first = al.groupby('merchant')['anchor'].min()
            known = susp.dropna()
            hit = first.index.isin(known.index)
            r['precision'] = _round(hit.mean(), 3) if len(first) else np.nan
            target = known[(known >= a_start) & (known <= a_end)]
            caught = first.reindex(target.index).dropna()
            r['susp_in_range'] = len(target)
            r['recall'] = _round(len(caught) / len(target), 3) if len(target) else np.nan
            lead = (target.reindex(caught.index) - caught).dt.days
            r['recall_early'] = _round((lead >= 0).sum() / len(target), 3) if len(target) else np.nan
            r['median_lead_days'] = float(lead.median()) if len(lead) else np.nan
        if loans is not None:
            # forward: matured loans in the lift_days after each alert vs loans of sellers this rule never alerted
            fwd = _expand(al['merchant'], al['anchor'], range(1, lift_days + 1))
            fwd['_cov'] = True
            Lf = loans[(loans['day'] > a_start) & (loans['day'] <= a_end + pd.Timedelta(days=lift_days))]
            Lf = Lf.merge(fwd, on=['merchant', 'day'], how='left')
            after = Lf[Lf['_cov'].fillna(False).astype(bool)]
            never = Lf[~Lf['merchant'].isin(set(al['merchant']))]
            ra, ro = _rate(after), _rate(never)
            r.update(obs_after_alert=int(after['obs_n'].sum()), def_rate_after_alert=r4(ra),
                     def_rate_never_alerted=r4(ro), lift_after_alert=r2(ra / ro) if ro else np.nan)
            # in window: matured loans inside the recent window of fired days vs all other loans (looks back)
            s_, e_ = rec[k[1]]
            cov = _expand(fired['merchant'], fired['anchor'], [-(b_ - 1) for b_ in range(s_, e_ + 1)])
            cov['_cov'] = True
            Lw = loans[(loans['day'] >= a_start) & (loans['day'] <= a_end)].merge(cov, on=['merchant', 'day'], how='left')
            inn = Lw['_cov'].fillna(False).astype(bool)
            ra, ro = _rate(Lw[inn]), _rate(Lw[~inn])
            r.update(obs_in_window=int(Lw.loc[inn, 'obs_n'].sum()), def_rate_in_window=r4(ra),
                     def_rate_outside=r4(ro), lift_in_window=r2(ra / ro) if ro else np.nan)
        rows.append(r)
    done = {tuple(r[c] for c in keys) for r in rows}
    for k in tests.index:                               # rules that never had a candidate row
        if tuple(k) not in done:
            rows.append(dict(zip(keys, k), rule_type=kind.get(k[0], 'flag'), tests=int(tests[k]), fired=0, alerts=0,
                             alerts_per_day=0.0, sellers_alerted=0))
    out = pd.DataFrame(rows)
    sort = [c for c in ['precision', 'recall', 'alerts'] if c in out.columns]
    return out.sort_values(sort, ascending=False, na_position='last').reset_index(drop=True)


def _intervals(det, comparisons):
    """Seller day ranges covered by the recent window of each fired day / alert, per rule, with
    overlapping or touching ranges merged (each transaction then falls in at most one range)."""
    keys = ['metric', 'comparison', 'unit', 'test']
    rec = {c['name']: tuple(c['recent']) for c in comparisons}
    rules = det[keys].drop_duplicates().reset_index(drop=True)
    rules['rid'] = np.arange(len(rules))
    parts = []
    for basis, col in [('fired', 'fired'), ('alert', 'alert')]:
        ev = det[det[col]].merge(rules, on=keys)
        if not len(ev):
            continue
        s_ = ev['comparison'].map(lambda c: rec[c][0]).values
        e_ = ev['comparison'].map(lambda c: rec[c][1]).values
        parts.append(pd.DataFrame({'rid': ev['rid'].values, 'basis': basis, 'merchant': ev['merchant'].values,
                                   'start': ev['anchor'].values - pd.to_timedelta(e_ - 1, unit='D'),
                                   'end': ev['anchor'].values - pd.to_timedelta(s_ - 1, unit='D')}))
    if not parts:
        return rules, pd.DataFrame(columns=['rid', 'basis', 'merchant', 'start', 'end'])
    iv = pd.concat(parts, ignore_index=True).sort_values(['rid', 'basis', 'merchant', 'start'])
    g = ['rid', 'basis', 'merchant']
    prev_end = iv.groupby(g)['end'].transform(lambda x: x.cummax().shift())
    new = prev_end.isna() | (iv['start'] > prev_end + pd.Timedelta(days=1))
    iv['_k'] = new.cumsum()
    iv = iv.groupby(g + ['_k'], as_index=False).agg(start=('start', 'min'), end=('end', 'max')).drop(columns='_k')
    return rules, iv


# ---------------------------------------------------------------------------- main
def run_fisher_backtest(df, config, spark=None):
    """Rolling backtest of Fisher-test triggers. Every day in the anchor range plays 'today'.

    Returns a dict: ok, detail (pandas: one row per tested seller x day x rule), summary
    (pandas: one row per rule), outcomes (pandas: per rule, transactions in the recent window of
    fired days / alerts vs the rest: suspicious, default and observed, by transaction and by
    client), failed_step and error when it stopped."""
    from pyspark.sql import functions as F
    cfg = dict(DEFAULTS); cfg.update(config or {})
    spark = spark or df.sparkSession
    metrics, comparisons = cfg['metrics'], cfg['comparisons']
    peer = bool(cfg['peer_cols'])
    fb = list(cfg['peer_fallback_cols'] or [])
    levels = ([('p', '_g')] + ([('p2', '_g2')] if fb else [])) if peer else []
    units = list(cfg['units'])
    steps = ['check_inputs', 'anchor_range'] + ['spark_tests_' + u for u in units] + \
            ['fisher_and_q', 'alerts', 'spark_labels', 'spark_outcomes', 'summary']
    res = {'ok': False, 'detail': None, 'summary': None, 'outcomes': None, 'failed': []}
    st = {}
    t0 = time.time()

    def step(i, name, fn):
        _log(f"[{i}/{len(steps)}] {name} ...")
        t = time.time()
        out = fn()
        _log(f"      done in {time.time() - t:.1f}s")
        return out

    def check():
        need = [cfg['date_col'], cfg['merchant_col'], cfg['customer_col']] + list(cfg['peer_cols']) + fb
        miss = [c for c in need if c not in df.columns]
        if miss:
            raise ValueError(f"columns not in df: {', '.join(miss)}")
        if fb and not peer:
            raise ValueError('peer_fallback_cols needs peer_cols')
        if cfg['bh_scope'] not in ('rule', 'day'):
            raise ValueError("bh_scope must be 'rule' or 'day'")
        names = [m['name'] for m in metrics]
        if len(set(names)) != len(names):
            raise ValueError('metric names must be unique')
        for cmp_ in comparisons:
            (s1, e1), (s2, e2) = cmp_['recent'], cmp_['base']
            if not (1 <= s1 <= e1 and 1 <= s2 <= e2):
                raise ValueError(f"comparison {cmp_['name']}: windows need 1 <= start <= end")
        exprs = [m['expr'] for m in metrics if m['kind'] == 'flag']
        if cfg['susp_cond']:
            exprs.append(cfg['susp_cond'])
        for c in [cfg['susp_date_col'], cfg['def_col'], cfg['obs_col']]:
            if c and c not in df.columns:
                raise ValueError(f"column not in df: {c}")
        for e in exprs:
            df.limit(0).select(F.expr(e)).schema   # raises if the SQL condition does not parse
        grp = lambda cs: F.concat_ws(' | ', *[F.coalesce(F.col(c).cast('string'), F.lit('(null)')) for c in cs]) \
            if cs else F.lit('all')
        g, g2 = grp(cfg['peer_cols'] if peer else []), grp(fb)
        st['base'] = df.select(
            F.to_date(F.col(cfg['date_col'])).alias('_d'), F.col(cfg['merchant_col']).cast('string').alias('_m'),
            F.col(cfg['customer_col']).cast('string').alias('_c'), g.alias('_g'), g2.alias('_g2'),
            *[F.when(F.expr(m['expr']), 1).otherwise(0).alias('_f_' + m['name']) for m in metrics if m['kind'] == 'flag']
        ).where(F.col('_d').isNotNull() & F.col('_m').isNotNull())

    def anchors():
        r = st['base'].agg(F.min('_d').alias('lo'), F.max('_d').alias('hi')).collect()[0]
        if r['lo'] is None:
            raise ValueError('df has no rows with a date and a seller')
        lo, hi = pd.Timestamp(r['lo']), pd.Timestamp(r['hi'])
        if cfg['skip_last_day']:
            hi -= pd.Timedelta(days=1)
        max_back = _max(_max(c['recent'][1], c['base'][1]) for c in comparisons)
        a_s = pd.Timestamp(cfg['anchor_start']) if cfg['anchor_start'] else lo + pd.Timedelta(days=max_back - 1)
        a_e = _min(pd.Timestamp(cfg['anchor_end']), hi) if cfg['anchor_end'] else hi
        if a_s > a_e:
            raise ValueError(f"no anchor days: data {lo.date()} to {hi.date()}, the longest window needs "
                             f"{max_back} days, so anchors would start {a_s.date()}")
        st['a_s'], st['a_e'], st['max_back'] = a_s, a_e, max_back
        st['n_days'] = (a_e - a_s).days + 1
        _log(f"      data {lo.date()} to {hi.date()}; anchors {a_s.date()} to {a_e.date()} ({st['n_days']} days)")

    def tests_for(unit):
        def run():
            wins = _windows(comparisons)
            cnt, cached = _spark_counts(st['base'], unit, metrics, wins, levels, str(st['a_s'].date()), str(st['a_e'].date()), spark)
            cnt = cnt.persist()
            t = _spark_tests(cnt, unit, metrics, comparisons, wins, levels, cfg, spark).persist()
            fam = t.groupBy('anchor', 'metric', 'comparison', 'unit', 'test').agg(F.count(F.lit(1)).alias('n_tests')).toPandas()
            # only rows leaning the suspicious way (a*d > b*c) can reach a small p; the rest stay in the family count
            cand = t.where(F.col('a') * F.col('d') > F.col('b') * F.col('c'))
            n = cand.count()
            if n + _sum(len(v) for v in st.get('det', [])) > cfg['max_rows']:
                raise ValueError(f"{n:,} candidate rows for unit={unit} is over max_rows={cfg['max_rows']:,}. "
                                 f"Raise min_total/min_flag, shorten the anchor range, or raise max_rows")
            pdf = cand.toPandas()
            t.unpersist(); cnt.unpersist()
            for c_ in cached:
                c_.unpersist()
            st.setdefault('det', []).append(pdf); st.setdefault('fam', []).append(fam)
            _log(f"      {int(fam['n_tests'].sum()):,} tests, {n:,} leaning up (kept)")
        return run

    def fisher():
        det = pd.concat(st['det'], ignore_index=True)
        fam = pd.concat(st['fam'], ignore_index=True)
        det['anchor'] = pd.to_datetime(det['anchor']); fam['anchor'] = pd.to_datetime(fam['anchor'])
        for c in 'abcd':
            det[c] = det[c].astype(np.int64)
        det['share_recent'] = det['a'] / (det['a'] + det['b']).where(lambda s: s > 0)
        det['share_ref'] = det['c'] / (det['c'] + det['d']).where(lambda s: s > 0)
        det['odds_ratio'], det['or_lo'], det['or_hi'] = odds_ratio(det['a'], det['b'], det['c'], det['d'])
        det['p'] = fisher_greater(det['a'], det['b'], det['c'], det['d'])
        keys = ['anchor'] if cfg['bh_scope'] == 'day' else ['anchor', 'metric', 'comparison', 'unit', 'test']
        det = det.merge(fam.groupby(keys, as_index=False)['n_tests'].sum(), on=keys, how='left')
        det['q'] = np.nan
        for _, idx in det.groupby(keys).groups.items():
            det.loc[idx, 'q'] = bh_qvalues(det.loc[idx, 'p'].values, det.loc[idx[0], 'n_tests'])
        det['fired'] = (det['q'] <= cfg['q_max']) & (det['odds_ratio'] >= cfg['or_min'])
        st['detail'], st['fam'] = det, fam
        _log(f"      {int(det['fired'].sum()):,} fired")

    def alerts():
        st['detail'] = _alerts(st['detail'], int(cfg['cooldown']))
        _log(f"      {int(st['detail']['alert'].sum()):,} alerts after the {cfg['cooldown']}-day cooldown")

    def labels():
        st['susp'] = st['loans'] = None
        m = F.col(cfg['merchant_col']).cast('string')
        if cfg['susp_cond']:
            dt = F.to_date(F.col(cfg['susp_date_col'])) if cfg['susp_date_col'] else F.to_date(F.col(cfg['date_col']))
            s = (df.where(F.expr(cfg['susp_cond'])).groupBy(m.alias('merchant'))
                 .agg(F.min(dt).alias('susp_date')).toPandas())
            st['susp'] = pd.to_datetime(s.set_index('merchant')['susp_date'])
            _log(f"      {len(s):,} suspicious sellers")
        if cfg['def_col'] and cfg['obs_col']:
            d = F.to_date(F.col(cfg['date_col']))
            l = (df.where(F.col(cfg['obs_col']).cast('int') == 1)
                 .where(d >= F.lit(str((st['a_s'] - pd.Timedelta(days=st['max_back'])).date())).cast('date'))
                 .groupBy(m.alias('merchant'), d.alias('day'))
                 .agg(F.count(F.lit(1)).alias('obs_n'), F.sum(F.col(cfg['def_col']).cast('int')).alias('def_n')).toPandas())
            l['day'] = pd.to_datetime(l['day'])
            st['loans'] = l
            _log(f"      {int(l['obs_n'].sum()):,} observed loans (from the first window day)")

    def outcomes():
        """Transactions in the recent window of fired days / alerts, per rule, against the rest of the
        anchor range: counts by transaction and by distinct client (exact, each client once per rule)."""
        a_s, a_e = st['a_s'], st['a_e']
        rules, iv = _intervals(st['detail'], comparisons)
        iv['start'] = iv['start'].clip(lower=a_s); iv['end'] = iv['end'].clip(upper=a_e)
        iv = iv[iv['start'] <= iv['end']]
        has_s, has_d = bool(cfg['susp_cond']), bool(cfg['def_col'] and cfg['obs_col'])
        d = F.to_date(F.col(cfg['date_col']))
        one = lambda c: F.when(c, 1).otherwise(0)
        T = df.where(d.between(str(a_s.date()), str(a_e.date()))).select(
            F.col(cfg['merchant_col']).cast('string').alias('_m'), d.alias('_d'),
            F.col(cfg['customer_col']).cast('string').alias('_c'),
            (one(F.expr(cfg['susp_cond'])) if has_s else F.lit(0)).alias('_s'),
            (one(F.col(cfg['obs_col']).cast('int') == 1) if has_d else F.lit(0)).alias('_o'),
            (one((F.col(cfg['obs_col']).cast('int') == 1) & (F.col(cfg['def_col']).cast('int') == 1))
             if has_d else F.lit(0)).alias('_x')).persist()
        tx = lambda: [F.count(F.lit(1)).alias('txn'), F.sum('_s').alias('susp_txn'),
                      F.sum('_o').alias('obs_txn'), F.sum('_x').alias('def_txn')]
        tot = T.agg(*tx()).toPandas().iloc[0]
        per_c = T.groupBy('_c').agg(F.count(F.lit(1)).alias('n'), F.sum('_s').alias('ns'),
                                    F.sum('_o').alias('no'), F.sum('_x').alias('nx'))
        cl = per_c.agg(F.count(F.lit(1)).alias('client'), F.sum(one(F.col('ns') > 0)).alias('susp_client'),
                       F.sum(one(F.col('no') > 0)).alias('obs_client'),
                       F.sum(one(F.col('nx') > 0)).alias('def_client')).toPandas().iloc[0]
        allr = {**{k: int(tot[k] or 0) for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']},
                **{k: int(cl[k] or 0) for k in ['client', 'susp_client', 'obs_client', 'def_client']}}
        cov_t = cov_c = full = pd.DataFrame(columns=['rid', 'basis'])
        if len(iv):
            I = spark.createDataFrame(pd.DataFrame({'rid': iv['rid'].astype(int), 'basis': iv['basis'].astype(str),
                                                    '_im': iv['merchant'].astype(str),
                                                    '_is': iv['start'].dt.strftime('%Y-%m-%d'),
                                                    '_ie': iv['end'].dt.strftime('%Y-%m-%d')}))
            I = I.select('rid', 'basis', '_im', F.to_date('_is').alias('_is'), F.to_date('_ie').alias('_ie'))
            C = T.join(F.broadcast(I), (T['_m'] == I['_im']) & T['_d'].between(I['_is'], I['_ie'])).persist()
            cov_t = C.groupBy('rid', 'basis').agg(*tx()).toPandas()
            cc = C.groupBy('rid', 'basis', '_c').agg(F.count(F.lit(1)).alias('k'), F.sum('_s').alias('ks'),
                                                     F.sum('_o').alias('ko'), F.sum('_x').alias('kx'))
            cov_c = cc.groupBy('rid', 'basis').agg(
                F.count(F.lit(1)).alias('client'), F.sum(one(F.col('ks') > 0)).alias('susp_client'),
                F.sum(one(F.col('ko') > 0)).alias('obs_client'), F.sum(one(F.col('kx') > 0)).alias('def_client')).toPandas()
            # a client is outside the events if they have at least one transaction (of that kind) outside them
            full = cc.join(per_c, '_c').groupBy('rid', 'basis').agg(
                F.sum(one(F.col('k') == F.col('n'))).alias('client'),
                F.sum(one((F.col('ns') > 0) & (F.col('ks') == F.col('ns')))).alias('susp_client'),
                F.sum(one((F.col('no') > 0) & (F.col('ko') == F.col('no')))).alias('obs_client'),
                F.sum(one((F.col('nx') > 0) & (F.col('kx') == F.col('nx')))).alias('def_client')).toPandas()
            C.unpersist()
        T.unpersist()
        cnt = ['txn', 'client', 'susp_txn', 'susp_client', 'obs_txn', 'obs_client', 'def_txn', 'def_client']
        look = lambda tab, rid, basis: (tab[(tab['rid'] == rid) & (tab['basis'] == basis)].iloc[0]
                                        if len(tab) and ((tab['rid'] == rid) & (tab['basis'] == basis)).any() else None)
        kind = {m['name']: m['kind'] for m in metrics}
        rows = []
        for _, ru in rules.iterrows():
            for basis, other in [('fired', 'not_fired'), ('alert', 'not_alerted')]:
                t_, c_, f_ = look(cov_t, ru['rid'], basis), look(cov_c, ru['rid'], basis), look(full, ru['rid'], basis)
                inn = {k: int(t_[k]) if t_ is not None else 0 for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']}
                inn.update({k: int(c_[k]) if c_ is not None else 0 for k in ['client', 'susp_client', 'obs_client', 'def_client']})
                out = {k: allr[k] - inn[k] for k in ['txn', 'susp_txn', 'obs_txn', 'def_txn']}
                out.update({k: allr[k] - (int(f_[k]) if f_ is not None else 0)
                            for k in ['client', 'susp_client', 'obs_client', 'def_client']})
                for grp, v in [(basis, inn), (other, out)]:
                    r = {c: ru[c] for c in ['metric', 'comparison', 'unit', 'test']}
                    r.update(rule_type=kind.get(ru['metric'], 'flag'), group=grp, **{k: v[k] for k in cnt})
                    rows.append(r)
        o = pd.DataFrame(rows)
        if len(o):
            dv = lambda a, b: (o[a] / o[b].where(o[b] > 0)).round(4)
            o['susp_rate_txn'], o['susp_rate_client'] = dv('susp_txn', 'txn'), dv('susp_client', 'client')
            o['def_rate_txn'], o['def_rate_client'] = dv('def_txn', 'obs_txn'), dv('def_client', 'obs_client')
            if not has_s:
                o = o.drop(columns=['susp_txn', 'susp_client', 'susp_rate_txn', 'susp_rate_client'])
            if not has_d:
                o = o.drop(columns=['obs_txn', 'obs_client', 'def_txn', 'def_client', 'def_rate_txn', 'def_rate_client'])
        st['outcomes'] = o
        _log(f"      {len(iv):,} seller day ranges; outcomes for {len(rules)} rules")

    def summary():
        st['summary'] = _summary(st['detail'], st['fam'], st['n_days'], comparisons, metrics, st['susp'], st['loans'],
                                 st['a_s'], st['a_e'], int(cfg['lift_days']))
        cols = ['anchor', 'merchant', 'peer_group', 'metric', 'comparison', 'unit', 'test', 'a', 'b', 'c', 'd',
                'share_recent', 'share_ref', 'odds_ratio', 'or_lo', 'or_hi', 'p', 'q', 'n_tests', 'peer_sellers', 'peer_level',
                'fired', 'alert']
        st['detail'] = st['detail'][cols].sort_values(['anchor', 'p']).reset_index(drop=True)

    fns = [check, anchors] + [tests_for(u) for u in units] + [fisher, alerts, labels, outcomes, summary]
    for i, (name, fn) in enumerate(zip(steps, fns), 1):
        try:
            step(i, name, fn)
        except Exception as e:
            first = (str(e).strip().splitlines() or [type(e).__name__])[0]
            _log(f"\nFAILED at step {i}/{len(steps)}: {name}: {first}")
            rest = steps[i:]
            if rest:
                _log(f"  not run: {', '.join(rest)}")
            res.update(failed_step=name, error=str(e), failed=[name])
            return res
    res.update(ok=True, detail=st['detail'], summary=st['summary'], outcomes=st['outcomes'])
    _log(f"\nDone in {time.time() - t0:.0f}s: {len(st['detail']):,} detail rows, {len(st['summary'])} rules.")
    return res
